 "content": "from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r in range(h):
        inds = [c for c, v in enumerate(grid[r]) if v != bg]
        for a, b in zip(inds, inds[1:]):
            if b - a == 2 and grid[r][a] == grid[r][b] and grid[r][a+1] == bg:
                out[r][a+1] = 2
    for c in range(w):
        inds = [r for r in range(h) if grid[r][c] != bg]
        for a, b in zip(inds, inds[1:]):
            if b - a == 2 and grid[a][c] == grid[b][c] and grid[a+1][c] == bg:
                out[a+1][c] = 2
    return out
